arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -d '{"query":"query { __type(name: \"Mutation\") { fields(includeDeprecated: true) { name args { name type { name kind ofType { name kind ofType { name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if f['name'] in ('attachmentUpdate','issueUpdate'):
        print(f['name'])
        for a in f['args']:
            t=a['type']
            print('  ',a['name'], t['kind'], t['name'] or (t['ofType']['name'] if t['ofType'] else ''))
"

